import { Sprite, Texture } from 'pixi.js';

export class FadeOverlay extends Sprite {
    constructor(canClickThrough: boolean = false) {
        super(Texture.WHITE);

        this.tint = 0;
        this.alpha = 0.6;
        this.interactive = !canClickThrough;
        this.anchor.set(0.5);
    }

    public resize(width: number, height: number): void {
        this.width = width;
        this.height = height;
    }
}
